  goals:[["one","Cada columna tiene un solo creador"],["bill","Cada casa nueva recibe una primera factura"],["steward","La cuenta tiene dueño y responsable"],["found","Se encuentra al dueño de la tabla de cortes"]],
  capsShort:["Conectar","Atender","Operar"],capsH:"Capacidades",cons:["Punto de conexión","Cuenta","Corte"],key:"C crea · L lee",
